<?php require_once __DIR__ . '/_bootstrap.php'; $categories=b2cRows("SELECT c.id,c.name,c.description,COUNT(p.id) product_count FROM categories c LEFT JOIN products p ON p.category_id=c.id AND p.status='active' WHERE c.status='active' GROUP BY c.id ORDER BY c.name"); b2cPage('Categories','categories'); ?>
<div class="section-head"><div><h1>Browse categories</h1><p>Everything you need, organized for you.</p></div></div>
<?php if(!$categories): ?><div class="empty">Categories will appear here once our catalog is ready.</div><?php else: ?><section class="grid"><?php foreach($categories as $c): ?><a class="category-card" href="products.php?category=<?= (int)$c['id'] ?>"><span class="eyebrow">Collection</span><h3><?= e($c['name']) ?> →</h3><p class="muted"><?= e($c['description']??'Explore this collection') ?></p><strong><?= (int)$c['product_count'] ?> products</strong></a><?php endforeach; ?></section><?php endif; ?><?php b2cEnd(); ?>